const systemTheme=window.matchMedia("(prefers-color-scheme: dark)");
function readThemeChoice(){try{const value=localStorage.getItem(THEME_KEY);return ["light","dark","auto"].includes(value)?value:"auto"}catch{return "auto"}}
function resolvedTheme(choice){return choice==="auto"?(systemTheme.matches?"dark":"light"):choice}
function applyTheme(choice,saveChoice=false){if(!["light","dark","auto"].includes(choice))choice="auto";if(saveChoice){try{localStorage.setItem(THEME_KEY,choice)}catch{}}const theme=resolvedTheme(choice),root=document.documentElement;root.dataset.themeChoice=choice;root.dataset.theme=theme;const meta=document.querySelector('meta[name="theme-color"]');if(meta)meta.content=theme==="dark"?"#061f29":"#073b4c";document.querySelectorAll(".theme-option").forEach(button=>{const active=button.dataset.themeChoice===choice;button.classList.toggle("active",active);button.setAttribute("aria-checked",String(active))});const description=$("themeDescription");if(description)description.textContent=choice==="light"?"Světlý vzhled bude použit bez ohledu na nastavení zařízení.":choice==="dark"?"Tmavý vzhled bude použit bez ohledu na nastavení zařízení.":"Automaticky podle nastavení zařízení."}
function bindThemeSwitcher(){document.querySelectorAll(".theme-option").forEach(button=>button.onclick=()=>applyTheme(button.dataset.themeChoice,true));applyTheme(readThemeChoice());const followSystem=()=>{if(readThemeChoice()==="auto")applyTheme("auto")};if(systemTheme.addEventListener)systemTheme.addEventListener("change",followSystem);else if(systemTheme.addListener)systemTheme.addListener(followSystem)}
