let saveQueue=Promise.resolve();function save(){renderDashboard();const x=typeof structuredClone==="function"?structuredClone(db):JSON.parse(JSON.stringify(db));saveQueue=saveQueue.then(()=>DiveStorage.write(x)).catch(e=>{console.error(e);alert("Data se nepodařilo uložit do IndexedDB: "+e.message)});return saveQueue}
