function returnToDashboardDive(id=dashboardReturnDiveId){rememberDashboardDive(id);showView("dashboard");renderDashboard();requestAnimationFrame(()=>requestAnimationFrame(()=>{const card=document.querySelector(`.dive-card[data-id="${CSS.escape(String(id||""))}"]`);if(card){card.scrollIntoView({block:"center"});card.focus({preventScroll:true})}}))}
function diveMissingState(dive){const site=siteOf(dive?.siteId),location=!(site?.name||dive?.import?.siteNameOcr||dive?.siteNameOcr),country=!site?.country?.trim(),buddy=!((dive?.buddyIds||[]).length||(dive?.buddies||[]).filter(Boolean).length);return {location,country,buddy}}
function selectedMissingFields(){return [["location",$("missingLocation")?.checked],["country",$("missingCountry")?.checked],["buddy",$("missingBuddy")?.checked]].filter(([,checked])=>checked).map(([field])=>field)}
function missingFilterMode(){return document.querySelector('input[name="missingMode"]:checked')?.value||"any"}
function diveMatchesMissingFilter(dive){if(!missingFilterActive)return true;const fields=selectedMissingFields();if(!fields.length)return true;const state=diveMissingState(dive),tests=fields.map(field=>state[field]);return missingFilterMode()==="all"?tests.every(Boolean):tests.some(Boolean)}
function updateMissingFilterUi(){if(!db)return;const counts={location:0,country:0,buddy:0};db.dives.forEach(d=>{const state=diveMissingState(d);Object.keys(counts).forEach(key=>{if(state[key])counts[key]++})});$("missingLocationCount").textContent=counts.location;$("missingCountryCount").textContent=counts.country;$("missingBuddyCount").textContent=counts.buddy;const incomplete=db.dives.filter(d=>Object.values(diveMissingState(d)).some(Boolean)).length;$("missingFilterTotal").textContent=incomplete;$("toggleMissingFilter").classList.toggle("active",missingFilterActive);const fields=selectedMissingFields();const labels={location:"lokalita",country:"země",buddy:"buddy"};$("missingFilterStatus").textContent=missingFilterActive?`Aktivní filtr: ${fields.map(x=>labels[x]).join(", ")||"bez vybraných položek"} · ${missingFilterMode()==="all"?"musí chybět všechny":"stačí kterýkoliv údaj"}.`:"Filtr není aktivní."}
function currentAdvancedFilters(){return {country:$("filterCountry")?.value||"",site:$("filterSite")?.value||"",waterBody:$("filterWaterBody")?.value||"",timeOfDay:$("filterTimeOfDay")?.value||"",buddy:$("filterBuddy")?.value||"",year:$("filterYear")?.value||"",rating:$("filterRating")?.value||""}}
function advancedFilterCount(){return Object.values(advancedFilters).filter(Boolean).length}
function diveMatchesAdvancedFilter(dive){if(!advancedFilterActive)return true;const site=siteOf(dive.siteId),f=advancedFilters,c=dive.conditions||{};if(f.country&&String(site?.country||"")!==f.country)return false;if(f.site&&String(dive.siteId??"")!==f.site)return false;if(f.waterBody&&String(c.waterBodyId??"")!==f.waterBody)return false;if(f.timeOfDay&&String(c.timeOfDay||"day")!==f.timeOfDay)return false;if(f.buddy&&!(dive.buddyIds||[]).map(String).includes(f.buddy))return false;if(f.year&&diveYear(dive)!==f.year)return false;if(f.rating==="none"&&dive.rating!=null&&dive.rating!=="")return false;if(f.rating&&f.rating!=="none"){const r=Number(dive.rating)||0;if(f.rating==="5"?r!==5:r<Number(f.rating))return false}return true}
function diveMatchesSearch(dive){const q=$("search")?.value.trim().toLowerCase()||"";if(!q)return true;const site=siteOf(dive.siteId);return `${site?.name||""} ${site?.country||""} ${dive.date||""} ${dive.diveNumber||""}`.toLowerCase().includes(q)}
function optionList(select,items,blank,value){if(!select)return;select.innerHTML=`<option value="">${blank}</option>`+items.map(x=>`<option value="${esc(String(x.value))}">${esc(x.label)}</option>`).join("");select.value=value||""}
function populateAdvancedFilters(){const selected=currentAdvancedFilters(),sites=Object.values(db.sites||{}),countries=[...new Set(sites.map(x=>x.country).filter(Boolean))].sort((a,b)=>a.localeCompare(b,"cs")),filteredSites=selected.country?sites.filter(x=>x.country===selected.country):sites;optionList($("filterCountry"),countries.map(x=>({value:x,label:x})),"Všechny země",selected.country);optionList($("filterSite"),filteredSites.sort((a,b)=>(a.name||"").localeCompare(b.name||"","cs")).map(x=>({value:x.ssiId??x.id,label:[x.name,x.country].filter(Boolean).join(" · ")})),"Všechny lokality",selected.site);optionList($("filterWaterBody"),(window.catalogItems?.("waterBody",true)||[]).map(x=>({value:x.id,label:x.name})),"Všechny",selected.waterBody);optionList($("filterTimeOfDay"),(window.catalogItems?.("timeOfDay",true)||[]).map(x=>({value:x.id,label:x.name})),"Všechny",selected.timeOfDay);optionList($("filterBuddy"),Object.values(db.buddies||{}).sort((a,b)=>a.name.localeCompare(b.name,"cs")).map(x=>({value:x.id,label:x.name})),"Všichni",selected.buddy);optionList($("filterYear"),[...new Set(db.dives.map(d=>diveYear(d)))].sort((a,b)=>b.localeCompare(a)).map(x=>({value:x,label:x})),"Všechny roky",selected.year);$("filterRating").value=selected.rating||""}
function updateAdvancedFilterUi(){const count=advancedFilterActive?advancedFilterCount():0;$("advancedFilterCount").textContent=count;$("toggleAdvancedFilter").classList.toggle("active",count>0);const labels=[];if(advancedFilterActive){const f=advancedFilters;if(f.country)labels.push(f.country);if(f.site)labels.push(siteOf(Number(f.site))?.name||`Lokalita ${f.site}`);if(f.waterBody)labels.push(window.catalogLabel?.("waterBody",f.waterBody)||f.waterBody);if(f.timeOfDay)labels.push(window.catalogLabel?.("timeOfDay",f.timeOfDay)||f.timeOfDay);if(f.buddy)labels.push(db.buddies?.[f.buddy]?.name||"Buddy");if(f.year)labels.push(f.year);if(f.rating)labels.push(f.rating==="none"?"bez hodnocení":f.rating==="5"?"5 ★":`${f.rating} ★ a více`)}$("advancedFilterStatus").textContent=count?`Aktivní: ${labels.join(" · ")}`:"Filtr není aktivní."}
function nextHigherDive(current){const number=Number(current?.diveNumber);if(!Number.isFinite(number))return null;return [...db.dives].filter(d=>d.id!==current.id&&Number(d.diveNumber)>number&&diveMatchesMissingFilter(d)&&diveMatchesAdvancedFilter(d)&&diveMatchesSearch(d)).sort((a,b)=>Number(a.diveNumber)-Number(b.diveNumber)||String(a.date||"").localeCompare(String(b.date||"")))[0]||null}
function openNextDiveForEditing(current){const next=nextHigherDive(current);if(!next){alert(missingFilterActive?"Žádný další ponor s vyšším číslem neodpovídá aktivnímu filtru.":"Žádný další ponor s vyšším číslem není uložen.");openDetail(current.id);return}rememberDashboardDive(next.id);prepForm(next);showView("editView")}
function displayLookup(type,id){if(id==null)return "Nevyplněno";if(type==="waterBody"&&window.catalogLabel){const name=window.catalogLabel("waterBody",id);return name&&name!==String(id)?name:`Neznámá vodní plocha · ID ${id}`}return LOOKUPS[type]?.[id]||`ID ${id}`}
function siteOf(id){return id==null?null:db.sites[String(id)]}
function fmtDate(s){if(!s)return "";const [y,m,d]=s.split("-");return `${d}.${m}.${y}`}
function nextDiveNumber(){const nums=db.dives.map(d=>Number(d.diveNumber)).filter(n=>Number.isInteger(n)&&n>0);if(nums.length)return Math.max(...nums)+1;const start=Number(db.settings?.initialDiveNumber);return Number.isInteger(start)&&start>0?start:null}
let upcomingTermsExpanded=false;
function termDays(date){if(!date)return null;const today=new Date();today.setHours(0,0,0,0);const target=new Date(`${date}T00:00:00`);return Number.isNaN(target.getTime())?null:Math.round((target-today)/86400000)}
function termUrgency(days){return days<=0?"expired":days<=30?"soon":"warning"}
function termText(kind,days,date){const action=kind==="service"?"Revize":"Platnost";if(days<0)return `${action} je ${Math.abs(days)} dnů po termínu · ${fmtDate(date)}`;if(days===0)return `${action} končí dnes · ${fmtDate(date)}`;return `${action} za ${days} dnů · ${fmtDate(date)}`}
function upcomingTerms(){const terms=[];Object.values(db.serviceItems||{}).forEach(item=>{if(item.status==="retired")return;const days=termDays(item.nextDate);if(days!==null&&days<=90)terms.push({kind:"service",id:item.id,title:item.name||"Servis vybavení",date:item.nextDate,days})});Object.values(db.insurance||{}).forEach(item=>{const days=termDays(item.validUntil);if(days!==null&&days<=90)terms.push({kind:"insurance",id:item.id,title:[item.provider,item.product].filter(Boolean).join(" · ")||"Pojištění",date:item.validUntil,days})});return terms.sort((x,y)=>x.days-y.days||x.title.localeCompare(y.title,"cs"))}
function openUpcomingTerm(kind,id){showView("profileView");if(kind==="service"){activateProfileTab("service");setTimeout(()=>window.openServiceForm?.(id),0)}else{activateProfileTab("insurance");setTimeout(()=>openInsuranceForm(id),0)}}
function renderUpcomingTerms(){const list=$("upcomingTermsList");if(!list)return;const terms=upcomingTerms(),shown=upcomingTermsExpanded?terms:terms.slice(0,3);$("upcomingTermsBadge").textContent=terms.length;$("upcomingTermsBadge").classList.toggle("hidden",!terms.length);$("toggleUpcomingTerms").classList.toggle("hidden",terms.length<=3);$("toggleUpcomingTerms").textContent=upcomingTermsExpanded?"Skrýt":"Zobrazit vše";if(!terms.length){list.innerHTML='<div class="terms-ok"><span>✓</span><div><strong>Termíny jsou v pořádku</strong><small>Žádná revize ani pojištění nekončí během 90 dnů.</small></div></div>';return}list.innerHTML=shown.map(item=>`<button class="term-item term-${termUrgency(item.days)}" type="button" data-term-kind="${item.kind}" data-term-id="${item.id}"><span class="term-dot" aria-hidden="true"></span><span><strong>${esc(item.title)}</strong><small>${termText(item.kind,item.days,item.date)}</small></span><b>›</b></button>`).join("");document.querySelectorAll("[data-term-id]").forEach(button=>button.onclick=()=>openUpcomingTerm(button.dataset.termKind,button.dataset.termId))}
function renderDashboard(){renderUpcomingTerms();const q=$("search").value.trim().toLowerCase();const dives=[...db.dives].sort((a,b)=>`${b.date}${b.startTime||""}`.localeCompare(`${a.date}${a.startTime||""}`));const filtered=dives.filter(d=>{const site=siteOf(d.siteId),matchesSearch=!q||`${site?.name||""} ${site?.country||""} ${d.date} ${d.diveNumber||""}`.toLowerCase().includes(q);return matchesSearch&&diveMatchesMissingFilter(d)&&diveMatchesAdvancedFilter(d)});updateMissingFilterUi();updateAdvancedFilterUi();$("statCount").textContent=db.dives.length;const loggedNums=db.dives.map(d=>Number(d.diveNumber)).filter(n=>Number.isFinite(n)&&n>0);$("statLoggedNumber").textContent=loggedNums.length?Math.max(...loggedNums):"–";const mins=db.dives.reduce((sum,d)=>sum+(d.durationMinutes||0),0);$("statTime").textContent=`${Math.floor(mins/60)} h ${mins%60} min`;const depths=db.dives.map(d=>d.maxDepthM).filter(Number.isFinite);$("statDepth").textContent=depths.length?`${Math.max(...depths).toFixed(1).replace(".",",")} m`:"–";const groups=new Map();filtered.forEach(d=>{const year=diveYear(d);if(!groups.has(year))groups.set(year,[]);groups.get(year).push(d)});const years=[...groups.keys()].sort((a,b)=>b.localeCompare(a));if(!q&&localStorage.getItem(DIVE_YEARS_KEY)===null&&years.length){openDiveYears.add(years[0]);saveOpenDiveYears()}const card=d=>{const site=siteOf(d.siteId);return `<button class="dive-card" data-id="${d.id}" type="button"><div><h3>${d.diveNumber?`#${d.diveNumber} · `:""}${esc(site?.name||d.import?.siteNameOcr||d.siteNameOcr||`Lokalita ${d.siteId||"neuvedena"}`)}</h3><p>${fmtDate(d.date)}${d.startTime?` · ${d.startTime}`:""}${site?.country?` · ${esc(site.country)}`:""}</p></div><div class="dive-metrics"><span>${Number.isFinite(d.maxDepthM)?d.maxDepthM.toFixed(1).replace(".",","):"–"} m</span><span>${d.durationMinutes} min</span></div></button>`};$("diveList").innerHTML=years.map(year=>{const items=groups.get(year),expanded=(q||missingFilterActive||advancedFilterActive)?true:openDiveYears.has(year),yearMinutes=items.reduce((sum,d)=>sum+(d.durationMinutes||0),0),yearDepths=items.map(d=>d.maxDepthM).filter(Number.isFinite),summary=`${items.length} ${items.length===1?"ponor":items.length>=2&&items.length<=4?"ponory":"ponorů"} · ${Math.floor(yearMinutes/60)} h ${yearMinutes%60} min${yearDepths.length?` · max. ${Math.max(...yearDepths).toFixed(1).replace(".",",")} m`:""}`;return `<section class="dive-year-group${expanded?" is-open":""}" data-year="${esc(year)}"><button class="dive-year-header" type="button" aria-expanded="${expanded}" ${(q||missingFilterActive||advancedFilterActive)?'disabled aria-disabled="true"':''}><span class="dive-year-arrow" aria-hidden="true">›</span><span class="dive-year-title"><strong>${esc(year)}</strong><small>${summary}</small></span></button><div class="dive-year-items" ${expanded?"":"hidden"}>${expanded?items.map(card).join(""):""}</div></section>`}).join("");$("emptyState").classList.toggle("hidden",filtered.length>0||db.dives.length>0);document.querySelectorAll(".dive-year-header:not([disabled])").forEach(button=>button.addEventListener("click",()=>{const year=button.closest(".dive-year-group").dataset.year;if(openDiveYears.has(year))openDiveYears.delete(year);else openDiveYears.add(year);saveOpenDiveYears();renderDashboard()}));document.querySelectorAll(".dive-card").forEach(button=>button.addEventListener("click",()=>openDetail(button.dataset.id)));if(diveListObserver){diveListObserver.disconnect();diveListObserver=null}}

